INSERT INTO "OccupationState" (id,"releaseId","updatedAt") VALUES ('active','catwalks-occupations-20260909-v1',CURRENT_TIMESTAMP);

CREATE FUNCTION protect_occupation_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Occupation releases and observations are immutable; publish a new reviewed release'; END;
$$;
CREATE TRIGGER occupation_release_immutable BEFORE UPDATE OR DELETE ON "OccupationRelease" FOR EACH ROW EXECUTE FUNCTION protect_occupation_evidence();
CREATE TRIGGER occupation_observation_immutable BEFORE UPDATE OR DELETE ON "OccupationObservation" FOR EACH ROW EXECUTE FUNCTION protect_occupation_evidence();
ALTER TABLE "OccupationState" ADD CONSTRAINT occupation_state_singleton CHECK (id='active');
ALTER TABLE "Job" ADD CONSTRAINT occupation_state_valid CHECK (
 "occupationStatus" IN ('PENDING','CLASSIFIED','FAMILY_ONLY','NO_RULE','AMBIGUOUS','INPUT_REVIEW')
 AND (("occupationStatus"='CLASSIFIED')=("occupationCode" IS NOT NULL))
 AND ("occupationStatus"='PENDING' OR "occupationReleaseId" IS NOT NULL));
CREATE FUNCTION validate_job_occupation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE document jsonb; definition jsonb; family jsonb;
BEGIN
 IF NEW."occupationReleaseId" IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW."occupationReleaseId",NEW."occupationCode",NEW."jobFunction",NEW."occupationGroup") IS NOT DISTINCT FROM ROW(OLD."occupationReleaseId",OLD."occupationCode",OLD."jobFunction",OLD."occupationGroup") THEN RETURN NEW; END IF;
 SELECT manifest INTO STRICT document FROM "OccupationRelease" WHERE id=NEW."occupationReleaseId";
 IF NEW."occupationCode" IS NOT NULL THEN
  SELECT x INTO definition FROM jsonb_array_elements(document->'occupations') x WHERE x->>'key'=NEW."occupationCode";
  IF definition IS NULL OR definition->>'family' IS DISTINCT FROM NEW."jobFunction" THEN RAISE EXCEPTION 'Occupation/family mismatch for %',NEW.id; END IF;
 END IF;
 IF NEW."jobFunction" IS NOT NULL THEN
  SELECT x INTO family FROM jsonb_array_elements(document->'families') x WHERE x->>'key'=NEW."jobFunction";
  IF family IS NULL OR family->>'group' IS DISTINCT FROM NEW."occupationGroup" THEN RAISE EXCEPTION 'Occupation family/group mismatch for %',NEW.id; END IF;
 ELSIF NEW."occupationGroup" IS NOT NULL THEN RAISE EXCEPTION 'Occupation group without family for %',NEW.id;
 END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER job_occupation_integrity BEFORE INSERT OR UPDATE OF "occupationReleaseId","occupationCode","jobFunction","occupationGroup" ON "Job" FOR EACH ROW EXECUTE FUNCTION validate_job_occupation();
